def enlaces_para_avisos_vigentes(apps, schema_editor):
    """Los avisos ya enviados pedían iniciar sesión: se les da un enlace para el acceso sin cuenta."""
    Resultado = apps.get_model("resultados", "Resultado")
    EnlaceAcceso = apps.get_model("resultados", "EnlaceAcceso")
    for r in Resultado.objects.filter(estado="notificado"):
        aviso = r.notificaciones.order_by("-intento", "-creada").first()
        if aviso is None:
            continue
        token = secrets.token_urlsafe(32)
        aviso.enlace_simulado = f"/acceso/{token}/"
        aviso.save(update_fields=["enlace_simulado"])
        EnlaceAcceso.objects.create(aviso=aviso, resultado=r, token_hash=hashlib.sha256(token.encode()).hexdigest(),
                                    expira=timezone.now() + timedelta(hours=72))


